<?php require_once __DIR__.'/lib/auth.php';startAppSession();if(currentUser()){header('Location: index.php');exit;}$error='';$notice=isset($_GET['reset'])?'Password updated. You can sign in now.':(isset($_GET['setup'])?'Admin created. Sign in with your new credentials.':'');if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: index.php');exit;}$error='Invalid email or password.';}$mode='login';require __DIR__.'/views/auth.php';
